function gruppi(c){
  c.innerHTML = GRUPPI;
  avviaGruppi();
  nomiDeiGruppi();
}

/* ── il codice della pagina, come l'ha scritto Design: non si tocca ──
   Nel disegno l'involucro gira da sé appena la pagina è letta; qui la
   pagina nasce dentro gruppi(), quindi lo si chiama lì. */
function avviaGruppi(){
(function () {
  "use strict";

  var ATTESA = "[ in attesa ]";
  var vuoto = function (v) { return v === undefined || v === null || v === ""; };
  function svuota(n) { while (n && n.firstChild) n.removeChild(n.firstChild); }

  function scrivi(nodo, valore) {
    svuota(nodo);
    if (vuoto(valore)) {
      var v = document.createElement("span");
      v.className = "vac";
      v.textContent = ATTESA;
      nodo.appendChild(v);
    } else {
      nodo.appendChild(document.createTextNode(String(valore)));
    }
  }

  function riempi(dati) {
    dati = dati || {};
    var chi = dati.chi || {};
    var rotte = dati.rotte || {};

    /* le porte: la rotta è la strada, l'evento è la scorciatoia di chi non ne ha */
    [].forEach.call(document.querySelectorAll(".sv-ger .card"), function (a) {
      var r = rotte[a.getAttribute("data-area")];
      if (!vuoto(r)) a.setAttribute("href", r);
    });

    /* le persone nei ruoli: la struttura è nel disegno, i nomi arrivano da fuori */
    [].forEach.call(document.querySelectorAll(".sv-ger [data-chi]"), function (n) {
      scrivi(n, chi[n.getAttribute("data-chi")]);
    });

    /* i vicinati, se ne arrivano */
    var box = document.querySelector(".sv-ger [data-vicinati]");
    if (!box) return;
    svuota(box);
    var vicinati = dati.vicinati || [];
    box.hidden = !vicinati.length;

    if (!vicinati.length) return;

    var cap = document.createElement("div");
    cap.className = "cap";
    cap.textContent = "I vicinati";
    box.appendChild(cap);

    vicinati.forEach(function (v) {
      var e = document.createElement("div");
      e.className = "vv";
      var b = document.createElement("b");
      scrivi(b, v.nome);
      e.appendChild(b);
      e.appendChild(tre(v));
      box.appendChild(e);
    });
  }

  function tre(v) {
    var g = document.createElement("div");
    g.className = "tre";
    [["l\u2019amministratore", "amministratore"],
     ["il formatore", "formatore"],
     ["la comunicazione", "comunicazione"]].forEach(function (r) {
      var d = document.createElement("div");
      var em = document.createElement("em");
      em.textContent = r[0];
      d.appendChild(em);
      var s = document.createElement("span");
      scrivi(s, v[r[1]]);
      d.appendChild(s);
      g.appendChild(d);
    });
    return g;
  }

  /* L'ascolto del tocco vive sul documento, che nel guscio non muore mai:
     la stanza rinasce a ogni visita, il segno resta, e l'ascolto non si
     riattacca. Chi torna dieci volte manda un evento solo. */
  if (!window.SpazioVivo || !window.SpazioVivo.__ascoltoAree) {
  document.addEventListener("click", function (e) {
    var a = e.target.closest ? e.target.closest(".sv-ger .card") : null;
    if (!a) return;
    if (a.getAttribute("href") !== "#") return;   /* ha una rotta: lasciala andare */
    e.preventDefault();
    document.dispatchEvent(new CustomEvent("spazio-vivo:area", {
      detail: { area: a.getAttribute("data-area") } }));
  });
  window.SpazioVivo = window.SpazioVivo || {};
  window.SpazioVivo.__ascoltoAree = true;
  }

  /* la guida del Nexus è già in carica; il resto arriva dal dato */
  riempi({ chi: { "svil.guida": "Gabriele Dettori" } });

  window.SpazioVivo = window.SpazioVivo || {};
  window.SpazioVivo.gerarchia = riempi;
})();
}

/* ── i nomi di chi tiene cosa ──
   ⚠️ In attesa dei nomi. Finché non ci sono non si chiama niente: la
      pagina resta com'è e ogni posto vacante dice [ in attesa ].
      L'unico nome che si vede è quello che mette Design nel disegno.
   ⭐ Il giorno che i nomi ci sono, qui si restituisce
      { chi:{…}, rotte:{…} } e si passa a window.SpazioVivo.gerarchia().
   ⛔ Non si inventano né nomi né tabella: si chiede. */
function nomiDeiGruppi(){
  return;
}
